package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;
/** Real WebView bridge timeout/UI recovery; mocked image provider only, no paid requests. */
public final class IllustrationRecoveryFlowTest extends DocumentEditorTest {
 void selectText()throws Exception{h.js("(()=>{const b=document.querySelector('#doc-body'),r=document.createRange();r.selectNodeContents(b);b.focus();getSelection().removeAllRanges();getSelection().addRange(r);document.dispatchEvent(new Event('selectionchange'))})()");Thread.sleep(150);}
 void readyPanel()throws Exception{selectText();click("#doc-illustrate");until("!!document.querySelector('#illustration-prompt')");h.js("document.querySelector('#illustration-prompt').value='米白底墨绿知识图解';document.querySelector('#illustration-prompt').dispatchEvent(new Event('input'))");}
 @Override public void onStart(){Bundle result=new Bundle();try{
  h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");h.call("saveImageSettings",new JSONObject().put("settings",new JSONObject().put("apiKey","synthetic-only")));model();
  h.js("window.__recoverNative=LifeNative;window.__jobs=[];window.__attempts=0;window.__posts=0;window.__acks=0;window.__mode='timeout';window.__listFail=false;window.__realTimeout=setTimeout;window.setTimeout=(fn,ms,...args)=>__realTimeout(fn,ms===60000?200:ms,...args);LifeNative={call:(a,p,id)=>{const v=JSON.parse(p);if(a==='getIllustrationJobs'){nativeReply(__listFail?{id,error:'合成列表离线'}:{id,data:__jobs});return;}if(a==='createIllustration'){__attempts++;if(__jobs.some(j=>['UNCERTAIN','PENDING','SUBMITTING'].includes(j.status))){nativeReply({id,error:'本记录上次提交结果未确认；请核对控制台后，在下方解除占用。'});return;}__posts++;const j={...v,createdAt:Date.now(),status:__mode==='failed'?'FAILED':__mode==='success'?'PENDING':'UNCERTAIN',error:__mode==='failed'?'百炼限流，未受理本次请求；稍后重试。':__mode==='success'?'':'提交结果未确认；请核对控制台。'};if(__mode==='success')j.taskId='synthetic-id';__jobs.push(j);if(__mode==='timeout')return;if(__mode==='success')__listFail=true;nativeReply({id,data:j});return;}if(a==='ackIllustration'){__acks++;if(!v.confirmed)throw Error('explicit confirmation missing');__jobs=__jobs.filter(j=>j.id!==v.id);nativeReply({id,data:true});return;}if(a==='refreshIllustration'){nativeReply({id,error:'合成网络不可用'});return;}__recoverNative.call(a,p,id)}}");
  open("learning");input("断网提交恢复验证","用于配图的合成正文，正文应始终保留。");readyPanel();
  h.js("window.__savedBridge=LifeNative.call;window.__waitLists=[];LifeNative.call=(a,p,id)=>{if(a==='getIllustrationJobs'){__waitLists.push(id);return;}__savedBridge(a,p,id)}");
  click("#illustration-generate");until("!document.querySelector('#illustration-generate').disabled&&document.querySelector('#illustration-message').textContent.includes('提交结果未确认')");
  check(h.js("__waitLists.length>0").equals("true"),"Submit unlocks even while background job-list bridge has no reply");
  h.js("LifeNative.call=__savedBridge;__waitLists.forEach(id=>nativeReply({id,data:__jobs}))");until("!!document.querySelector('[data-release]')");
  check(h.js("document.querySelector('#illustration-message').textContent.includes('提交结果未确认')&&!document.querySelector('#illustration-message').textContent.includes('正在提交')").equals("true"),"Bridge timeout replaces submitting text and unlocks button");
  h.js("dispatchEvent(new Event('online'));RecordIllustrator.resume()");Thread.sleep(300);check(h.js("__posts===1&&__attempts===1").equals("true"),"Connectivity recovery never resubmits a paid job");
  click("#illustration-generate");until("!document.querySelector('#illustration-generate').disabled");check(h.js("__posts===1&&__attempts===2&&document.querySelector('#illustration-message').textContent.includes('解除占用')").equals("true"),"Retry blocked by old job shows actionable reason, not submitting");
  click("[data-release]");until("document.querySelector('#confirm-dialog').open");check(h.js("document.querySelector('#confirm-message').textContent.includes('重复扣费')").equals("true"),"Manual resolution explains non-cancellation and duplicate billing risk");click("#confirm-cancel");check(h.js("__acks===0&&__jobs.length===1").equals("true"),"Cancel leaves uncertain task intact");
  click("[data-release]");click("#confirm-ok");until("__jobs.length===0&&!document.querySelector('[data-release]')");check(h.js("__posts===1&&__acks===1").equals("true"),"Explicit resolution clears occupancy but never generates");
  h.js("__mode='failed'");click("#illustration-generate");until("!document.querySelector('#illustration-generate').disabled");check(h.js("document.querySelector('#illustration-message').textContent.includes('未受理')&&!document.querySelector('[data-release]')").equals("true"),"Definite HTTP rejection is retryable, not uncertain");h.screenshot("illustration-rejected.png");
  h.js("window.__persist=RecordEditor.persist;RecordEditor.persist=async()=>{throw Error('合成记录保存失败')}");click("#illustration-generate");until("!document.querySelector('#illustration-generate').disabled");check(h.js("__posts===2&&document.querySelector('#illustration-message').textContent==='合成记录保存失败'").equals("true"),"Draft save failure shows error without POST or stuck button");h.js("RecordEditor.persist=__persist;__mode='success'");
  click("#illustration-generate");until("!document.querySelector('#illustration-generate').disabled");h.js("RecordIllustrator.resume()");Thread.sleep(150);check(h.js("__posts===3&&document.querySelector('#illustration-message').textContent.includes('已提交')&&!document.querySelector('#illustration-message').textContent.includes('正在提交')").equals("true"),"Accepted task stays submitted even if list refresh fails");h.screenshot("illustration-recovered.png");
  h.js("__listFail=false");click("#illustration-close");readyPanel();check(h.js("!!document.querySelector('[data-query]')&&!document.querySelector('[data-release]')").equals("true"),"Reopening panel recovers known task for query, not release");click("[data-query]");until("!document.querySelector('[data-query]').disabled");check(h.js("__posts===3&&document.querySelector('#illustration-message').textContent.includes('网络不可用')").equals("true"),"Failed query surfaces in panel without another generation");
  check(h.js("DocumentRich.serialize(document.querySelector('#doc-body')).includes('正文应始终保留')").equals("true"),"All failure/recovery paths preserve original note");
  result.putString("stream","PASS IllustrationRecoveryFlowTest: "+passed+" checks\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable ex){try{h.screenshot("illustration-recovery-failure.png");}catch(Exception ignored){}result.putString("stream","FAIL IllustrationRecoveryFlowTest after "+passed+": "+ex+"\n");finish(Activity.RESULT_CANCELED,result);}}
}
